            raise ValueError(f"Invalid register address {addr:#04x}")

        if addr == 0x00:  # TEMP is read-only
            return

        if nbytes == 1:
            mask = 0xFF00
            data = (data << 8) & mask
            self.regs[addr] = (self.regs[addr] & ~mask) | data
        else:
            self.regs[addr] = data & 0xFFFF

