class TMP102_Simulator(BaseVirtualSensor):
    REG_TEMP = 0x00
    REG_CONFIG = 0x01
    REG_TLOW = 0x02
    REG_THIGH = 0x03

    RESET_VALUES = {
        REG_TEMP: 0x0000,
        REG_CONFIG: 0x60A0,
        REG_TLOW: 0x4B00,
        REG_THIGH: 0x5000,
    }

    def __init__(self):
        super().__init__()
        for addr, reset_value in self.RESET_VALUES.items():
            self.regs[addr] = reset_value

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr}")

        value = self.regs[addr]
        if nbytes == 1:
            return (value >> 8) & 0xFF
        return value

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr}")

        if addr == self.REG_TEMP:
            return  # TEMP is read-only

        if nbytes == 1:
            mask = 0xFF << 8
            data = (data & 0xFF) << 8
            self.regs[addr] = (self.regs[addr] & ~mask) | data
        else:
            self.regs[addr] = data & 0xFFFF

